{
  "findings": [
    {
      "check_id": "CKV_AWS_389",
      "title": "Public IP address assignment enabled",
      "resource": "aws_launch_configuration.lc",
      "severity": "MEDIUM",
      "explanation": "The 'associate_public_ip_address' is set to true, which exposes the instance to the public internet. This increases the attack surface and should be avoided unless absolutely necessary."
    },
    {
      "check_id": "CKV_AWS_79",
      "title": "Instance Metadata Service Version 1 enabled",
      "resource": "aws_launch_configuration.lc",
      "severity": "MEDIUM",
      "explanation": "The launch configuration does not explicitly enforce the use of Instance Metadata Service Version 2 (IMDSv2). IMDSv1 is less secure and susceptible to SSRF attacks."
    },
    {
      "check_id": "CKV_AWS_8",
      "title": "EBS volumes not encrypted",
      "resource": "aws_launch_configuration.lc",
      "severity": "MEDIUM",
      "explanation": "The launch configuration does not specify encryption for the root EBS volume. Unencrypted volumes can expose sensitive data if compromised."
    }
  ],
  "patched_code": "resource \"aws_launch_configuration\" \"lc\" {\n  name          = \"test_ecs\"\n  image_id      = data.aws_ami.amazon_linux.id\n  instance_type = \"t2.micro\"\n  lifecycle {\n    create_before_destroy = true\n  }\n  iam_instance_profile        = aws_iam_instance_profile.ecs_service_role.name\n  key_name                    = var.key_name\n  security_groups             = [aws_security_group.ec2-sg.id]\n  associate_public_ip_address = false\n  metadata_options {\n    http_tokens = \"required\"\n  }\n  root_block_device {\n    encrypted = true\n  }\n  user_data                   = <<EOF\nsudo apt-get update\nsudo echo \"ECS_CLUSTER=${var.cluster_name}\" >> /etc/ecs/ecs.config\nEOF\n}",
  "fix_summary": "Disabled public IP address assignment by setting 'associate_public_ip_address' to false. Enforced IMDSv2 by adding 'metadata_options' with 'http_tokens' set to 'required'. Enabled encryption for the root EBS volume by adding 'root_block_device' with 'encrypted' set to true."
}
